import 'package:animations/animations.dart';
import 'package:flutter/material.dart';

class OpenContainerExample extends StatelessWidget {
  const OpenContainerExample({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('OpenContainer 예제')),
      body: ListView.builder(
        padding: const EdgeInsets.all(16),
        itemCount: 10,
        itemBuilder: (context, index) {
          return Padding(
            padding: const EdgeInsets.only(bottom: 16),
            child: OpenContainer<bool>(
              // 전환 시간
              transitionDuration: const Duration(milliseconds: 500),

              // 열릴 때 배경색
              openColor: Theme.of(context).scaffoldBackgroundColor,
              closedColor: Colors.white,

              // 닫힌 상태의 모서리 둥글기
              closedElevation: 2,
              closedShape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(12),
              ),

              // 닫힌 상태 (카드)
              closedBuilder: (context, openContainer) {
                return _ProductCard(
                  index: index,
                  onTap: openContainer,  // 탭 시 컨테이너 열기
                );
              },

              // 열린 상태 (상세 화면)
              openBuilder: (context, closeContainer) {
                return _ProductDetailPage(
                  index: index,
                  onClose: () => closeContainer(returnValue: true),
                );
              },

              // 결과값 받기
              onClosed: (result) {
                if (result == true) {
                  ScaffoldMessenger.of(context).showSnackBar(
                    const SnackBar(content: Text('상세 화면에서 돌아옴')),
                  );
                }
              },
            ),
          );
        },
      ),

      // FAB에도 OpenContainer 적용 가능
      floatingActionButton: OpenContainer(
        transitionDuration: const Duration(milliseconds: 500),
        openBuilder: (context, _) => const _CreateItemPage(),
        closedElevation: 6,
        closedShape: const CircleBorder(),
        closedColor: Theme.of(context).colorScheme.primary,
        closedBuilder: (context, openContainer) {
          return SizedBox(
            height: 56,
            width: 56,
            child: Center(
              child: Icon(
                Icons.add,
                color: Theme.of(context).colorScheme.onPrimary,
              ),
            ),
          );
        },
      ),
    );
  }
}

class _ProductCard extends StatelessWidget {
  final int index;
  final VoidCallback onTap;

  const _ProductCard({required this.index, required this.onTap});

  @override
  Widget build(BuildContext context) {
    return InkWell(
      onTap: onTap,
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Row(
          children: [
            Container(
              width: 80,
              height: 80,
              decoration: BoxDecoration(
                color: Colors.primaries[index % Colors.primaries.length],
                borderRadius: BorderRadius.circular(8),
              ),
              child: const Icon(Icons.shopping_bag, color: Colors.white),
            ),
            const SizedBox(width: 16),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text('상품 ${index + 1}', style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 16)),
                  const SizedBox(height: 4),
                  Text('상품 설명입니다...', style: TextStyle(color: Colors.grey.shade600)),
                  const SizedBox(height: 4),
                  Text('₩${(index + 1) * 10000}', style: const TextStyle(fontWeight: FontWeight.bold)),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class _ProductDetailPage extends StatelessWidget {
  final int index;
  final VoidCallback onClose;

  const _ProductDetailPage({required this.index, required this.onClose});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text('상품 ${index + 1}'),
        leading: IconButton(
          icon: const Icon(Icons.close),
          onPressed: onClose,
        ),
      ),
      body: SingleChildScrollView(
        child: Column(
          children: [
            Container(
              width: double.infinity,
              height: 300,
              color: Colors.primaries[index % Colors.primaries.length],
              child: const Icon(Icons.shopping_bag, color: Colors.white, size: 100),
            ),
            Padding(
              padding: const EdgeInsets.all(16),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text('상품 ${index + 1}', style: const TextStyle(fontSize: 24, fontWeight: FontWeight.bold)),
                  const SizedBox(height: 8),
                  Text('₩${(index + 1) * 10000}', style: const TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: Colors.blue)),
                  const SizedBox(height: 16),
                  const Text('이 상품의 상세 설명입니다. OpenContainer를 사용하면 카드가 자연스럽게 전체 화면으로 확장됩니다.'),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class _CreateItemPage extends StatelessWidget {
  const _CreateItemPage();

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('새 상품 추가')),
      body: const Center(child: Text('FAB에서 확장된 화면')),
