import 'package:animations/animations.dart';
import 'package:flutter/material.dart';

class SharedAxisExample extends StatefulWidget {
  const SharedAxisExample({super.key});

  @override
  State<SharedAxisExample> createState() => _SharedAxisExampleState();
}

class _SharedAxisExampleState extends State<SharedAxisExample> {
  int _currentIndex = 0;
  bool _isForward = true;  // 전환 방향

  final List<Widget> _pages = [
    const _OnboardingPage(
      title: '환영합니다!',
      description: '앱의 주요 기능을 소개합니다.',
      icon: Icons.waving_hand,
      color: Colors.blue,
    ),
    const _OnboardingPage(
      title: '빠른 검색',
      description: '원하는 것을 빠르게 찾아보세요.',
      icon: Icons.search,
      color: Colors.green,
    ),
    const _OnboardingPage(
      title: '시작하기',
      description: '지금 바로 시작해보세요!',
      icon: Icons.rocket_launch,
      color: Colors.orange,
    ),
  ];

  void _goToPage(int index) {
    setState(() {
      _isForward = index > _currentIndex;
      _currentIndex = index;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('SharedAxis 예제')),
      body: Column(
        children: [
          // 전환 타입 선택
          Padding(
            padding: const EdgeInsets.all(16),
            child: SegmentedButton<SharedAxisTransitionType>(
              selected: {SharedAxisTransitionType.horizontal},
              segments: const [
                ButtonSegment(
                  value: SharedAxisTransitionType.horizontal,
                  label: Text('X축'),
                ),
                ButtonSegment(
                  value: SharedAxisTransitionType.vertical,
                  label: Text('Y축'),
                ),
                ButtonSegment(
                  value: SharedAxisTransitionType.scaled,
                  label: Text('Z축'),
                ),
              ],
              onSelectionChanged: (_) {},
            ),
          ),

          // 페이지 전환 영역
          Expanded(
            child: PageTransitionSwitcher(
              duration: const Duration(milliseconds: 400),
              reverse: !_isForward,  // 뒤로 갈 때 반대 방향 애니메이션
              transitionBuilder: (child, primaryAnimation, secondaryAnimation) {
                return SharedAxisTransition(
                  animation: primaryAnimation,
                  secondaryAnimation: secondaryAnimation,
                  transitionType: SharedAxisTransitionType.horizontal,
                  child: child,
                );
              },
              child: _pages[_currentIndex],
            ),
          ),

          // 페이지 인디케이터
          Padding(
            padding: const EdgeInsets.all(16),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: List.generate(_pages.length, (index) {
                return GestureDetector(
                  onTap: () => _goToPage(index),
                  child: Container(
                    width: 12,
                    height: 12,
                    margin: const EdgeInsets.symmetric(horizontal: 4),
                    decoration: BoxDecoration(
                      shape: BoxShape.circle,
                      color: _currentIndex == index
                          ? Theme.of(context).primaryColor
                          : Colors.grey.shade300,
                    ),
                  ),
                );
              }),
            ),
          ),

          // 네비게이션 버튼
          Padding(
            padding: const EdgeInsets.all(16),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                TextButton(
                  onPressed: _currentIndex > 0
                      ? () => _goToPage(_currentIndex - 1)
                      : null,
                  child: const Text('이전'),
                ),
                ElevatedButton(
                  onPressed: _currentIndex < _pages.length - 1
                      ? () => _goToPage(_currentIndex + 1)
                      : () {
                          // 마지막 페이지에서 완료 처리
                          Navigator.pop(context);
                        },
                  child: Text(
                    _currentIndex < _pages.length - 1 ? '다음' : '시작하기',
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

class _OnboardingPage extends StatelessWidget {
  final String title;
  final String description;
  final IconData icon;
  final Color color;

  const _OnboardingPage({
    required this.title,
    required this.description,
    required this.icon,
    required this.color,
  });

  @override
  Widget build(BuildContext context) {
    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Icon(icon, size: 120, color: color),
        const SizedBox(height: 32),
        Text(
          title,
          style: const TextStyle(fontSize: 28, fontWeight: FontWeight.bold),
        ),
        const SizedBox(height: 16),
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: 32),
          child: Text(
            description,
            textAlign: TextAlign.center,
            style: TextStyle(fontSize: 16, color: Colors.grey.shade600),
          ),
        ),
      ],
    );
  }
}

import 'package:animations/animations.dart';
import 'package:flutter/material.dart';

class FadeThroughExample extends StatefulWidget {
  const FadeThroughExample({super.key});

  @override
  State<FadeThroughExample> createState() => _FadeThroughExampleState();
}

class _FadeThroughExampleState extends State<FadeThroughExample> {
  int _currentIndex = 0;

  final List<Widget> _pages = [
    const _TabPage(title: '홈', icon: Icons.home, color: Colors.blue),
    const _TabPage(title: '검색', icon: Icons.search, color: Colors.green),
    const _TabPage(title: '알림', icon: Icons.notifications, color: Colors.orange),
    const _TabPage(title: '프로필', icon: Icons.person, color: Colors.purple),
  ];

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('FadeThrough 예제')),
      body: PageTransitionSwitcher(
        duration: const Duration(milliseconds: 300),
        transitionBuilder: (child, primaryAnimation, secondaryAnimation) {
          return FadeThroughTransition(
            animation: primaryAnimation,
            secondaryAnimation: secondaryAnimation,
            child: child,
          );
        },
        child: _pages[_currentIndex],
      ),
      bottomNavigationBar: NavigationBar(
        selectedIndex: _currentIndex,
        onDestinationSelected: (index) {
          setState(() {
            _currentIndex = index;
          });
        },
        destinations: const [
          NavigationDestination(icon: Icon(Icons.home), label: '홈'),
          NavigationDestination(icon: Icon(Icons.search), label: '검색'),
          NavigationDestination(icon: Icon(Icons.notifications), label: '알림'),
          NavigationDestination(icon: Icon(Icons.person), label: '프로필'),
        ],
      ),
    );
  }
}

class _TabPage extends StatelessWidget {
  final String title;
  final IconData icon;
  final Color color;

  const _TabPage({
    required this.title,
    required this.icon,
    required this.color,
  });

  @override
  Widget build(BuildContext context) {
    // key를 지정해야 PageTransitionSwitcher가 위젯 변경을 인식
    return Container(
      key: ValueKey(title),
      color: color.withOpacity(0.1),
      child: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Icon(icon, size: 80, color: color),
            const SizedBox(height: 16),
            Text(
              title,
              style: TextStyle(
                fontSize: 24,
                fontWeight: FontWeight.bold,
                color: color,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:animations/animations.dart';
import 'package:flutter/material.dart';

class FadeScaleExample extends StatelessWidget {
  const FadeScaleExample({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('FadeScale 예제')),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            // 1. showModal 함수로 다이얼로그 표시
            ElevatedButton(
              onPressed: () {
                showModal<void>(
                  context: context,
                  configuration: const FadeScaleTransitionConfiguration(
                    transitionDuration: Duration(milliseconds: 300),
                    reverseTransitionDuration: Duration(milliseconds: 200),
                  ),
                  builder: (context) {
                    return AlertDialog(
                      title: const Text('FadeScale 다이얼로그'),
                      content: const Text('중앙에서 확대되며 나타납니다.'),
                      actions: [
                        TextButton(
                          onPressed: () => Navigator.pop(context),
                          child: const Text('확인'),
                        ),
                      ],
                    );
                  },
                );
              },
              child: const Text('FadeScale 다이얼로그'),
            ),

            const SizedBox(height: 16),

            // 2. 커스텀 모달 바텀 시트
            ElevatedButton(
              onPressed: () {
                showModal<void>(
                  context: context,
                  configuration: const FadeScaleTransitionConfiguration(),
                  builder: (context) {
                    return Center(
                      child: Container(
                        margin: const EdgeInsets.all(32),
                        padding: const EdgeInsets.all(24),
                        decoration: BoxDecoration(
                          color: Colors.white,
                          borderRadius: BorderRadius.circular(16),
                        ),
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            const Icon(
                              Icons.check_circle,
                              size: 80,
                              color: Colors.green,
                            ),
                            const SizedBox(height: 16),
                            const Text(
                              '성공!',
                              style: TextStyle(
                                fontSize: 24,
                                fontWeight: FontWeight.bold,
                              ),
                            ),
                            const SizedBox(height: 8),
                            const Text('작업이 완료되었습니다.'),
                            const SizedBox(height: 24),
                            ElevatedButton(
                              onPressed: () => Navigator.pop(context),
                              child: const Text('확인'),
                            ),
                          ],
                        ),
                      ),
                    );
                  },
                );
              },
              child: const Text('커스텀 모달'),
            ),

            const SizedBox(height: 16),

            // 3. AnimatedSwitcher와 FadeScaleTransition 조합
            const _AnimatedContent(),
          ],
        ),
      ),
    );
  }
}

class _AnimatedContent extends StatefulWidget {
  const _AnimatedContent();

  @override
  State<_AnimatedContent> createState() => _AnimatedContentState();
}

class _AnimatedContentState extends State<_AnimatedContent>
    with SingleTickerProviderStateMixin {
  late AnimationController _controller;
  bool _isVisible = false;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 300),
    );
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  void _toggle() {
    setState(() {
      _isVisible = !_isVisible;
      if (_isVisible) {
        _controller.forward();
      } else {
        _controller.reverse();
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        ElevatedButton(
          onPressed: _toggle,
          child: Text(_isVisible ? '숨기기' : '나타내기'),
        ),
        const SizedBox(height: 16),
        FadeScaleTransition(
          animation: _controller,
          child: _isVisible
              ? Card(
                  child: Padding(
                    padding: const EdgeInsets.all(24),
                    child: Column(
                      children: [
                        const Icon(Icons.star, size: 48, color: Colors.amber),
                        const SizedBox(height: 8),
                        const Text('FadeScale 위젯!'),
                      ],
                    ),
                  ),
                )
              : const SizedBox.shrink(),
        ),
      ],
    );
  }
}
